-- ERP_DB Sample Data - PART 3
-- PP (Production Planning), HR, CRM, SRM modules
-- =====================================================

-- =====================================================
-- 23. BILLS OF MATERIAL (25 records)
-- =====================================================


-- =====================================================
-- 24. BOM ITEMS (75 records - 3 components per BOM)
-- =====================================================

SELECT 
  bom.id,
  (SELECT id FROM materials WHERE material_code IN ('MAT0001','MAT0002','MAT0003','MAT0004','MAT0005','MAT0006','MAT0007','MAT0008','MAT0009','MAT0010') ORDER BY RANDOM() LIMIT 1),
  50 + (ABS(HASHTEXT(bom.material_id::TEXT || 'comp1')) % 200),
  'EA',
  1
FROM bills_of_material bom;

SELECT 
  bom.id,
  (SELECT id FROM materials WHERE material_code IN ('MAT0011','MAT0012','MAT0013','MAT0014','MAT0015','MAT0016','MAT0017','MAT0018','MAT0019','MAT0020') ORDER BY RANDOM() LIMIT 1),
  10 + (ABS(HASHTEXT(bom.material_id::TEXT || 'comp2')) % 50),
  'EA',
  2
FROM bills_of_material bom;

SELECT 
  bom.id,
  (SELECT id FROM materials WHERE material_code IN ('MAT0021','MAT0022','MAT0023','MAT0024','MAT0025') ORDER BY RANDOM() LIMIT 1),
  5 + (ABS(HASHTEXT(bom.material_id::TEXT || 'comp3')) % 20),
  'EA',
  3
FROM bills_of_material bom;

-- =====================================================
-- 25. WORK CENTERS (30 records)
-- =====================================================


-- =====================================================
-- 26. ROUTINGS (25 records)
-- =====================================================


-- =====================================================
-- 27. ROUTING OPERATIONS (100 records)
-- =====================================================

SELECT 
  r.id,
  (SELECT id FROM work_centers WHERE plant_id = r.plant_id ORDER BY RANDOM() LIMIT 1),
  1,
  'Standard',
  30 + (ABS(HASHTEXT(r.routing_number || 'op1')) % 120),
  15 + (ABS(HASHTEXT(r.routing_number || 'setup1')) % 60)
FROM routings r;

SELECT 
  r.id,
  (SELECT id FROM work_centers WHERE plant_id = r.plant_id ORDER BY RANDOM() LIMIT 1),
  2,
  'Standard',
  45 + (ABS(HASHTEXT(r.routing_number || 'op2')) % 150),
  20 + (ABS(HASHTEXT(r.routing_number || 'setup2')) % 90)
FROM routings r;

SELECT 
  r.id,
  (SELECT id FROM work_centers WHERE plant_id = r.plant_id ORDER BY RANDOM() LIMIT 1),
  3,
  'Inspection',
  20 + (ABS(HASHTEXT(r.routing_number || 'op3')) % 60),
  5 + (ABS(HASHTEXT(r.routing_number || 'setup3')) % 15)
FROM routings r;

SELECT 
  r.id,
  (SELECT id FROM work_centers WHERE plant_id = r.plant_id ORDER BY RANDOM() LIMIT 1),
  4,
  'Standard',
  25 + (ABS(HASHTEXT(r.routing_number || 'op4')) % 75),
  10 + (ABS(HASHTEXT(r.routing_number || 'setup4')) % 40)
FROM routings r;

-- =====================================================
-- 28. PRODUCTION ORDERS (50 records)
-- =====================================================


-- =====================================================
-- 29. PRODUCTION CONFIRMATIONS (50 records)
-- =====================================================

SELECT 
  po.id,
  CASE WHEN po.status = 'Completed' THEN po.planned_end_date - INTERVAL '2 days'
       WHEN po.status = 'In Progress' THEN CURRENT_DATE
       ELSE NULL END,
  CASE WHEN po.status = 'Completed' THEN po.order_quantity 
       WHEN po.status = 'In Progress' THEN (po.order_quantity * 0.6)::NUMERIC(13,3)
       ELSE 0 END,
  CASE WHEN po.status = 'Completed' THEN (po.order_quantity * 0.02)::NUMERIC(13,3)
       WHEN po.status = 'In Progress' THEN 0
       ELSE 0 END,
  CASE WHEN po.status = 'Completed' THEN 'Posted'
       WHEN po.status = 'In Progress' THEN 'Posted'
       ELSE 'Draft' END
FROM production_orders po
WHERE po.status IN ('Completed', 'In Progress');

